export function newTable() {
  return { kind: 'table', map: new Map(), headerDefined: false }
}

export function newArray() {
  return { kind: 'array', items: [] }
}

export function newArrayOfTables() {
  return { kind: 'array-of-tables', items: [] }
}

export function newLeaf(kind, value) {
  return { kind, value }
}
"}

