import { newTable } from './nodes.js'
import { walkIntermediate } from './walk.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const INT_RE = /^[+-]?\d+(?:_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(?:_\d+)*(?:\.\d+(?:_\d+)*)?(?:[eE][+-]?\d+(?:_\d+)*)?$/
const HAS_FRACTION_OR_EXP = /[.eE]/

/** Parses the structural content of a single line of the document. */
export class LineParser {
  constructor(text, lineNo) {
    this.text = text
    this.len = text.length
    this.pos = 0
    this.lineNo = lineNo
  }

  err(reason) {
    return new ParseError(this.lineNo, reason)
  }

  peek() {
    return this.text[this.pos]
  }

  skipWS() {
    while (this.pos < this.len && (this.text[this.pos] === ' ' || this.text[this.pos] === '\t')) this.pos++
  }

  atLineEnd() {
    return this.pos >= this.len || this.text[this.pos] === '#' || this.text[this.pos] === ';'
  }

  parseName() {
    const c = this.peek()
    if (c === '"') return this.parseBasicString()
    if (c === "'") return this.parseLiteralString()
    const start = this.pos
    while (this.pos < this.len && NAME_CHAR.test(this.text[this.pos])) this.pos++
    if (this.pos === start) throw this.err('expected a name')
    return this.text.slice(start, this.pos)
  }

  parseDottedName() {
    const segments = []
    while (true) {
      this.skipWS()
      segments.push(this.parseName())
      this.skipWS()
      if (this.peek() === '.') {
        this.pos++
        continue
      }
      break
    }
    return segments
  }

  parseBasicString() {
    this.pos++ // consume opening quote
    let out = ''
    while (true) {
      if (this.pos >= this.len) throw this.err('unterminated string')
      const c = this.text[this.pos]
      if (c === '"') {
        this.pos++
        return out
      }
      if (c === '\\') {
        this.pos++
        if (this.pos >= this.len) throw this.err('unterminated string')
        const e = this.text[this.pos]
        switch (e) {
          case '"':
            out += '"'
            this.pos++
            break
          case '\\':
            out += '\\'
            this.pos++
            break
          case 'n':
            out += '\n'
            this.pos++
            break
          case 't':
            out += '\t'
            this.pos++
            break
          case 'r':
            out += '\r'
            this.pos++
            break
          case '0':
            out += '\0'
            this.pos++
            break
          case 'u': {
            this.pos++
            const hex = this.text.substr(this.pos, 4)
            if (hex.length < 4) throw this.err('unterminated string')
            if (!/^[0-9A-Fa-f]{4}$/.test(hex)) throw this.err('invalid escape \\u')
            out += String.fromCharCode(parseInt(hex, 16))
            this.pos += 4
            break
          }
          default:
            throw this.err(`invalid escape \\${e}`)
        }
      } else {
        out += c
        this.pos++
      }
    }
  }

  parseLiteralString() {
    this.pos++ // consume opening quote
    const start = this.pos
    while (true) {
      if (this.pos >= this.len) throw this.err('unterminated string')
      if (this.text[this.pos] === "'") {
        const s = this.text.slice(start, this.pos)
        this.pos++
        return s
      }
      this.pos++
    }
  }

  readRawToken() {
    const start = this.pos
    while (this.pos < this.len) {
      const c = this.text[this.pos]
      if (c === ' ' || c === '\t' || c === ',' || c === ']' || c === '}') break
      this.pos++
    }
    return this.text.slice(start, this.pos)
  }

  parseValue(path) {
    this.skipWS()
    if (this.atLineEnd() || this.peek() === ',' || this.peek() === ']' || this.peek() === '}') {
      throw this.err('expected a value')
    }
    const c = this.peek()
    if (c === '"') return { kind: 'string', value: this.parseBasicString() }
    if (c === "'") return { kind: 'string', value: this.parseLiteralString() }
    if (c === '[') return this.parseArray(path)
    if (c === '{') return this.parseInlineTable(path)
    const token = this.readRawToken()
    if (token === 'true') return { kind: 'boolean', value: true }
    if (token === 'false') return { kind: 'boolean', value: false }
    if (INT_RE.test(token)) {
      return { kind: 'integer', value: Number(token.replace(/_/g, '')) }
    }
    if (FLOAT_RE.test(token) && HAS_FRACTION_OR_EXP.test(token)) {
      return { kind: 'float', value: Number(token.replace(/_/g, '')) }
    }
    throw this.err(`invalid value ${token}`)
  }

  parseArray(path) {
    this.pos++ // consume '['
    const items = []
    let idx = 0
    while (true) {
      this.skipWS()
      if (this.atLineEnd()) throw this.err('unterminated array')
      if (this.peek() === ']') {
        this.pos++
        return { kind: 'array', items }
      }
      const v = this.parseValue(`${path}[${idx}]`)
      items.push(v)
      idx++
      this.skipWS()
      if (this.atLineEnd()) throw this.err('unterminated array')
      const c = this.peek()
      if (c === ',') {
        this.pos++
        continue
      }
      if (c === ']') {
        this.pos++
        return { kind: 'array', items }
      }
      throw this.err('trailing text after a value')
    }
  }

  parseInlineTable(path) {
    this.pos++ // consume '{'
    const table = newTable()
    this.skipWS()
    if (this.atLineEnd()) throw this.err('unterminated inline table')
    if (this.peek() === '}') {
      this.pos++
      return table
    }
    while (true) {
      this.skipWS()
      if (this.atLineEnd()) throw this.err('unterminated inline table')
      const segments = this.parseDottedName()
      this.skipWS()
      if (this.atLineEnd()) throw this.err('unterminated inline table')
      if (this.peek() !== '=') throw this.err('expected = in an inline table')
      this.pos++
      const inter = segments.slice(0, -1)
      const lastSeg = segments[segments.length - 1]
      const { table: destTable, path: interPath } = walkIntermediate(table, inter, path, this.lineNo)
      const finalPath = interPath ? `${interPath}.${lastSeg}` : lastSeg
      if (destTable.map.has(lastSeg)) throw this.err(`key ${finalPath} is defined twice`)
      const value = this.parseValue(finalPath)
      destTable.map.set(lastSeg, value)
      this.skipWS()
      if (this.atLineEnd()) throw this.err('unterminated inline table')
      const c = this.peek()
      if (c === ',') {
        this.pos++
        continue
      }
      if (c === '}') {
        this.pos++
        return table
      }
      throw this.err('trailing text after a value')
    }
  }
}
"}

