import { newTable } from './nodes.js'

/**
 * Walks a table through the given intermediate dotted-name segments,
 * creating tables along the way as needed. Returns the table reached
 * and the dotted path to it (built from basePath).
 */
export function walkIntermediate(startTable, segments, basePath, lineNo) {
  let node = startTable
  let path = basePath
  for (const seg of segments) {
    path = path ? `${path}.${seg}` : seg
    if (node.map.has(seg)) {
      const child = node.map.get(seg)
      if (child.kind === 'table') {
        node = child
      } else if (child.kind === 'array-of-tables') {
        node = child.items[child.items.length - 1]
      } else {
        throw new ParseError(lineNo, `${path} is not a table`)
      }
    } else {
      const t = newTable()
      node.map.set(seg, t)
      node = t
    }
  }
  return { table: node, path }
}
"}

