function handleHeader(p, root, lineNo) {
  p.pos++ // consume '['
  let isArray = false
  if (p.peek() === '[') {
    isArray = true
    p.pos++
  }
  p.skipWS()
  const segments = p.parseDottedName()
  p.skipWS()
  if (p.peek() !== ']') throw p.err('unterminated table header')
  p.pos++
  if (isArray) {
    if (p.peek() !== ']') throw p.err('unterminated table header')
    p.pos++
  }
  p.skipWS()
  if (!p.atLineEnd()) throw p.err('trailing text after a table header')

  const inter = segments.slice(0, -1)
  const lastSeg = segments[segments.length - 1]
  const { table, path } = walkIntermediate(root, inter, '', lineNo)
  const finalPath = path ? `${path}.${lastSeg}` : lastSeg

  let newCurrent
  if (!isArray) {
    if (table.map.has(lastSeg)) {
      const existing = table.map.get(lastSeg)
      if (existing.kind !== 'table') throw new ParseError(lineNo, `${finalPath} is not a table`)
      if (existing.headerDefined) throw new ParseError(lineNo, `table ${finalPath} is defined twice`)
      existing.headerDefined = true
      newCurrent = existing
    } else {
      const t = newTable()
      t.headerDefined = true
      table.map.set(lastSeg, t)
      newCurrent = t
    }
  } else {
    if (table.map.has(lastSeg)) {
      const existing = table.map.get(lastSeg)
      if (existing.kind !== 'array-of-tables') throw new ParseError(lineNo, `${finalPath} is not an array of tables`)
      const t = newTable()
      existing.items.push(t)
      newCurrent = t
    } else {
      const t = newTable()
      const arr = { kind: 'array-of-tables', items: [t] }
      table.map.set(lastSeg, arr)
      newCurrent = t
    }
  }
  return { table: newCurrent, path: finalPath }
}

function handleAssignment(p, currentTable, currentPath, lineNo) {
  const segments = p.parseDottedName()
  p.skipWS()
  if (p.peek() !== '=') throw p.err('expected key = value')
  p.pos++ // consume '='

  const inter = segments.slice(0, -1)
  const lastSeg = segments[segments.length - 1]
  const { table, path } = walkIntermediate(currentTable, inter, currentPath, lineNo)
  const finalPath = path ? `${path}.${lastSeg}` : lastSeg
  if (table.map.has(lastSeg)) throw p.err(`key ${finalPath} is defined twice`)

  const value = p.parseValue(finalPath)
  p.skipWS()
  if (!p.atLineEnd()) throw p.err('trailing text after a value')

  table.map.set(lastSeg, value)
}

/** Parses a full configuration document (an array of lines) into a table tree. */
export function parseDocument(lines) {
  const root = newTable()
  let currentTable = root
  let currentPath = ''

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const p = new LineParser(lines[i], lineNo)
    p.skipWS()
    if (p.atLineEnd()) continue
    if (p.peek() === '[') {
      const r = handleHeader(p, root, lineNo)
      currentTable = r.table
      currentPath = r.path
    } else {
      handleAssignment(p, currentTable, currentPath, lineNo)
    }
  }

  return root
}
