{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import fs from 'node:fs'
import { parseDocument } from './parser.js'
import { toJson, toKeys } from './format.js'
import { ParseError } from './errors.js'

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }
  const mode = args[0]

  const text = fs.readFileSync(0, 'utf8')
  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let root
  try {
    root = parseDocument(lines)
  } catch (e) {
    if (e instanceof ParseError) {
      process.stderr.write(`error: ${e.message}\n`)
      process.exit(2)
    }
    throw e
  }

  const out = mode === 'json' ? toJson(root) : toKeys(root)
  process.stdout.write(out)
  process.exit(0)
}

main()
"}

